<?php
namespace App\Domain\Solutions;
use App\Models\{Page,Solution}; use Illuminate\Support\Facades\DB; use Illuminate\Validation\ValidationException;
final class SolutionRelationManager { public function sync(Solution $s,array $solutionIds,array $pageIds):void{if(in_array($s->id,$solutionIds))throw ValidationException::withMessages(['related_solution_ids'=>'A solution cannot relate to itself.']);$solutionIds=array_values(array_unique($solutionIds));$pageIds=array_values(array_unique($pageIds));if(count($solutionIds)>6||count($pageIds)>6)throw ValidationException::withMessages(['relations'=>'A maximum of six related solutions and pages is allowed.']);if(Solution::whereIn('id',$solutionIds)->whereNotNull('archived_at')->exists()||Page::whereIn('id',$pageIds)->whereNotNull('archived_at')->exists())throw ValidationException::withMessages(['relations'=>'Archived targets cannot be selected.']);DB::transaction(function()use($s,$solutionIds,$pageIds){$s->relatedSolutions()->sync(collect($solutionIds)->mapWithKeys(fn($id,$i)=>[$id=>['display_order'=>$i+1]])->all());$s->relatedPages()->sync(collect($pageIds)->mapWithKeys(fn($id,$i)=>[$id=>['display_order'=>$i+1]])->all());});SolutionCache::forget($s->id);foreach($solutionIds as $id)SolutionCache::forget($id);} }
